              <div>
                <div style={{ fontSize: '1.05rem', fontWeight: 700, color: '#fff', fontFamily: '"Space Grotesk", sans-serif', marginBottom: '0.35rem' }}>{f.title}</div>
                <div style={{ fontSize: '0.85rem', color: 'var(--text-1)', lineHeight: 1.5 }}>{f.desc}</div>
              </div>
            </motion.div>
          </Link>
