                      <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#fff' }}>{sub.vessel?.name || 'Unknown Asset'}</div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--text-2)', marginTop: '0.15rem' }}>IMO: {sub.vessel?.imo_number} • {sub.vessel?.vessel_type}</div>
